import{_ as a,o as t,c as s,a4 as r}from"./chunks/framework.BRzJ4ijD.js";const p=JSON.parse('{"title":"故障检测、failure models","description":"","frontmatter":{},"headers":[],"relativePath":"distributed/concepts/failure.md","filePath":"distributed/concepts/failure.md","lastUpdated":1788475713000}'),o={name:"distributed/concepts/failure.md"};function n(i,e,l,d,c,h){return t(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="故障检测、failure-models" tabindex="-1">故障检测、failure models <a class="header-anchor" href="#故障检测、failure-models" aria-label="Permalink to &quot;故障检测、failure models&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>分布式算法建立在<strong>故障模型 (failure model)</strong> 假设上——节点会怎么死、网络会怎么丢。<strong>核心区分</strong>:</p><ul><li><strong>Crash-stop</strong>: 死了永远不回来。Paxos 经典模型。</li><li><strong>Crash-recovery</strong>: 死后能重启但是稳定存储 OK, Scribe / GFS master replication 用这个。</li><li><strong>Omission</strong>: 消息可能丢, 但节点本身能&quot;接收其他节点&quot; (重新传达)——网络层故障。</li><li><strong>Byzantine</strong>: 节点可任意行为 (撒谎、串改、应该发 5 但发 9), 需 Byzantine Fault Tolerance (BFT) 算法。</li></ul><p>不存在能容忍&quot;所有故障、又有 5 个 9 可用&quot;的算法——这是不可能的。设计分布式系统从<strong>选 failure model</strong> 开始——决定后面用什么算法。本章梳理各 model、failure detector、heartbeat、phi-accrual 算法、asynchronous vs synchronous 网络的根本限制。</p><hr><h2 id="一、failure-models" tabindex="-1">一、Failure Models <a class="header-anchor" href="#一、failure-models" aria-label="Permalink to &quot;一、Failure Models&quot;">​</a></h2><h3 id="crash-stop-fail-stop" tabindex="-1">Crash-stop (Fail-stop) <a class="header-anchor" href="#crash-stop-fail-stop" aria-label="Permalink to &quot;Crash-stop (Fail-stop)&quot;">​</a></h3><p>节点一旦死,<strong>永远不再发任何消息</strong>。 系统中越简单故障模型, 算法越容易写:</p><ul><li>节点之间互相发心跳; N 秒无心跳 → mark dead; leader 选举只看 evidence。</li><li>一旦不准 recovery, 重启就是新身份 (新 node id)。</li></ul><p><strong>Paxos 多副本经典</strong>模型。 zookeeper-3.x ZAB acceptors 假设 crash-stop (但应用程序 failrecovery may restart state).</p><h3 id="crash-recovery" tabindex="-1">Crash-recovery <a class="header-anchor" href="#crash-recovery" aria-label="Permalink to &quot;Crash-recovery&quot;">​</a></h3><p>节点死后可重启, 稳定存储 (persistent state) 保留 (e.g., Raft log fsync-ed)。这是真实工业系统的常态。</p><p><strong>关键</strong>: 不能区分&quot;crash恢复后&quot; 与 &quot;缓慢但已活&quot;的节点——所以算法 need <strong>stable leader election</strong> + log <strong>commit 后</strong>注意 re-sync (at-least-once or exactly-once semantics).</p><h3 id="omission" tabindex="-1">Omission <a class="header-anchor" href="#omission" aria-label="Permalink to &quot;Omission&quot;">​</a></h3><p>网络丢消息, 但节点本身正常。 分:</p><ul><li><strong>Send omission</strong>: 节点发送丢, 接收正常。</li><li><strong>Receive omission</strong>: 节点接收丢, 发送正常。</li></ul><p>Omission 看似温和, 但要<strong>至少 strong failure detector</strong> (Chandra-Toueg 1996) 才能 solve consensus。</p><h3 id="byzantine-lamport-shostak-pease-1982" tabindex="-1">Byzantine (Lamport-Shostak-Pease 1982) <a class="header-anchor" href="#byzantine-lamport-shostak-pease-1982" aria-label="Permalink to &quot;Byzantine (Lamport-Shostak-Pease 1982)&quot;">​</a></h3><p>节点可任意行为——撒谎、伪造、不响应、发出非协议消息。 Byzantine Generals Problem 假设至多 f 个 byzantine 节点, 算法需 N ≥ 3f+1 (i.e., 备用超过 fault)。<strong>N≥3f+1 是 lower bound</strong>;PBFT (Practical BFT, Castro-Liskov 1999) 是经典 BFT 算法。</p><p><strong>现代 BFT 应用</strong>:</p><ul><li><strong>区块链</strong>: Bitcoin PoW 算非典型 BFT (treat 作算力 majority); Tendermint、HotStuff、DiemBFT v1 是经典 BFT 算法。</li><li><strong>集群 servers</strong>: 银行系统少量使用 PBFT 派生。</li><li><strong>Spanner 复制组</strong>: 用 Paxos (crash-stop), 非 BFT。</li></ul><p>工程代价: BFT 比 crash-stop replication 算法负载 N=3f+1, 通信复杂 O(N²), 故都在 ≤20 replica 时用。</p><h3 id="hybrid-model" tabindex="-1">Hybrid Model <a class="header-anchor" href="#hybrid-model" aria-label="Permalink to &quot;Hybrid Model&quot;">​</a></h3><p>工程上<strong>多种 model 混合</strong>:</p><ul><li>Spanner Paxos group 假设 crash-stop + omission (message can be delayed indefinitely);Scribe 协议处理 omission。</li><li>BFT 区块链常 evidence treat extra Byzantine + crash-recovery 处理 by epoch leader rotating fast.</li></ul><hr><h2 id="二、failure-detector-形式化-chandra-toueg-1996" tabindex="-1">二、Failure Detector 形式化 (Chandra-Toueg 1996) <a class="header-anchor" href="#二、failure-detector-形式化-chandra-toueg-1996" aria-label="Permalink to &quot;二、Failure Detector 形式化 (Chandra-Toueg 1996)&quot;">​</a></h2><h3 id="completeness-vs-accuracy" tabindex="-1">Completeness vs Accuracy <a class="header-anchor" href="#completeness-vs-accuracy" aria-label="Permalink to &quot;Completeness vs Accuracy&quot;">​</a></h3><p>A failure detector 是 oracle 给每个 process 提供&quot;怀疑其他 process 已死&quot;的列表。 评估四个性质:</p><table tabindex="0"><thead><tr><th>性质</th><th>含义</th></tr></thead><tbody><tr><td><strong>Completeness (strong)</strong></td><td>所有 eventually crash 节点 eventually 被某 process 怀疑</td></tr><tr><td><strong>Completeness (weak)</strong></td><td>所有 crash 节点 eventually 被某 correct process 怀疑</td></tr><tr><td><strong>Accuracy (strong)</strong></td><td>correct process <strong>永远</strong>不被怀疑 (无 spurious marking)</td></tr><tr><td><strong>Accuracy (eventual)</strong></td><td>eventually, correct process 不再被怀疑</td></tr><tr><td><strong>Accuracy (weak)</strong></td><td>部分 correct process 不被怀疑</td></tr><tr><td><strong>Accuracy (monotonic)</strong></td><td>一旦不再怀疑 correct, 永远不再怀疑</td></tr></tbody></table><h3 id="detector-分类" tabindex="-1">Detector 分类 <a class="header-anchor" href="#detector-分类" aria-label="Permalink to &quot;Detector 分类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>Completeness</th><th>Accuracy</th></tr></thead><tbody><tr><td>Perfect (P)</td><td>Strong</td><td>Strong</td></tr><tr><td>Strong (S)</td><td>Strong</td><td>Weak + eventual</td></tr><tr><td>Eventually Strong (◇S)</td><td>Weak + strong</td><td>Weak + eventual</td></tr><tr><td>Eventually Perfect (◇P)</td><td>Strong</td><td>Eventual</td></tr></tbody></table><h3 id="consensus-可解的-algebra" tabindex="-1">Consensus 可解的 Algebra <a class="header-anchor" href="#consensus-可解的-algebra" aria-label="Permalink to &quot;Consensus 可解的 Algebra&quot;">​</a></h3><p>Chandra-Toueg 证明: <strong>◇S</strong> (eventually strong) failure detector + asynchronous 网络 + N ≥ 2f+1 nodes → consensus 可解。 这是 Paxos 的本质——◇S 是 Paxos 隐式假设的 detector (任何节点, eventually 不再怀疑正确的 leader)。</p><p>但<strong>纯异步网络</strong> 无假设时, FLP (Fischer-Lynch-Paterson 1985) 证明 consensus <strong>不可解</strong>——任意 consensus 算法都可能&quot;indefinitate&quot; due to one process can be forever uncertain → 死锁。</p><p>工程绕开 FLP: 引入<strong>随机化</strong> (Paxos proposer timeout + 随机 backoff); 引入◇S detector (heartbeat phi-accrual) eventually 结论。</p><hr><h2 id="三、heartbeat-与-phi-accrual-检测" tabindex="-1">三、Heartbeat 与 Phi-Accrual 检测 <a class="header-anchor" href="#三、heartbeat-与-phi-accrual-检测" aria-label="Permalink to &quot;三、Heartbeat 与 Phi-Accrual 检测&quot;">​</a></h2><h3 id="简单-threshold-heartbeat" tabindex="-1">简单 Threshold Heartbeat <a class="header-anchor" href="#简单-threshold-heartbeat" aria-label="Permalink to &quot;简单 Threshold Heartbeat&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node A 每 1s 给 B 发 PING。</span></span>
<span class="line"><span>B 间隔 5s 没收到 PING → 怀疑 A 挂了。</span></span></code></pre></div><p>threshold fixed → 太大延迟检测, 太小误报。</p><h3 id="phi-accrual-hayashibara-2004-cassandra-用" tabindex="-1">Phi-Accrual (Hayashibara 2004, Cassandra 用) <a class="header-anchor" href="#phi-accrual-hayashibara-2004-cassandra-用" aria-label="Permalink to &quot;Phi-Accrual (Hayashibara 2004, Cassandra 用)&quot;">​</a></h3><p><strong>Accrual</strong> 含义: 给每个 nodes 出&quot;故障 suspicion level&quot;, 是连续值, 而非二值 (alive/suspect)。 算法:</p><ol><li><strong>统计历史 arrival time</strong>。 维护最近 N 个心跳到达间隔的滑动均值。</li><li>假设 arrivals 服从正态分布 (实际用 exponential), 计算&quot;since last heartbeat, 经过大空隙 X 自此没来的概率&quot;是 phi 值。</li><li>phi &#39;越大, 越怀疑该节点死。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Phi(t) = -log10(P(t_now - t_last &gt; Δ | x drawn from past arrival distribution))</span></span></code></pre></div><h3 id="cassandra-用法" tabindex="-1">Cassandra 用法 <a class="header-anchor" href="#cassandra-用法" aria-label="Permalink to &quot;Cassandra 用法&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>phi_threshold = 8</span></span>
<span class="line"><span>every tick:</span></span>
<span class="line"><span>  for each node peer:</span></span>
<span class="line"><span>    phi = compute_phi(peer)</span></span>
<span class="line"><span>    if phi &gt; threshold:</span></span>
<span class="line"><span>       mark peer DOWN</span></span>
<span class="line"><span>    else:</span></span>
<span class="line"><span>       mark peer UP</span></span></code></pre></div><p>Cassandra 默认 threshold = 8——对应 ~99.99999% 确认死。 <strong>Phi-accrual 减少 false-positive</strong> 比固定阈值好——网络抖动带来短 delay 不会直接 mark down。</p><h3 id="swarm-etcd-gossip-failure-detection" tabindex="-1">Swarm/Etcd/Gossip Failure Detection <a class="header-anchor" href="#swarm-etcd-gossip-failure-detection" aria-label="Permalink to &quot;Swarm/Etcd/Gossip Failure Detection&quot;">​</a></h3><p>许多系统用 Gossip 协议扩散状态:</p><ul><li>SWIM (Scalable Weakly-consistent Infection-style Process Group Membership): 多节点联合加直; 每节点 round-robin ping 一个 random member; ping 失败, random K 间接 ping; 仍 fail 加直suspect。</li><li>Consul, Serf 用 SWIM 派生 implementation。</li><li>etcd 用 Raft heartbeat + lease (3s timeout) 是 RAFT-style; 比 SWIM 更强的 consensus-detector.</li></ul><hr><h2 id="四、lease-vs-heartbeat-based" tabindex="-1">四、Lease vs Heartbeat-based <a class="header-anchor" href="#四、lease-vs-heartbeat-based" aria-label="Permalink to &quot;四、Lease vs Heartbeat-based&quot;">​</a></h2><h3 id="lease" tabindex="-1">Lease <a class="header-anchor" href="#lease" aria-label="Permalink to &quot;Lease&quot;">​</a></h3><p>Leader lease 是分布时间&quot;硬 lease&quot;: leader 获 lease 后 lease 期内<strong>保证没人挑战</strong>。 lease 过期必须 renew, 否则下 leader 接管。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>grant lease to L1 valid [t0, t0+T_lease]</span></span>
<span class="line"><span>if lease expired, no other leader can be elected in [t0+T_lease + ε] (给予 grace period buffer)</span></span></code></pre></div><p>用于:</p><ul><li><strong>Chubby lease</strong>: 60s lease + renewal 30s, write 决策 on lease.</li><li><strong>etcd Raft leader lease</strong>: defaulted 1s, upgrade per cluster config.</li><li><strong>MongoDB multi-doc transactions lease</strong>: writes acquire 事务 timestamp within replica lease.</li></ul><h3 id="lease-与-flp-不冲突原因" tabindex="-1">Lease 与 FLP 不冲突原因 <a class="header-anchor" href="#lease-与-flp-不冲突原因" aria-label="Permalink to &quot;Lease 与 FLP 不冲突原因&quot;">​</a></h3><p>Lease 引入了<strong>时间维度</strong>——必同步式 + bound: 由于 bounded lease ⇒ bounded halting ⇒ exit FLP indefinite halting trap.</p><h3 id="安全性要求" tabindex="-1">安全性要求 <a class="header-anchor" href="#安全性要求" aria-label="Permalink to &quot;安全性要求&quot;">​</a></h3><p><strong>Clock skew 不能让 lease 过期时间误判</strong>: 系统必须给出统一 lease 时间-source。 实际工程: 给每节点 NTP 同步 + lease renew 用 Raft majority write 多副本 sync leader 的话同一 cluster time.</p><hr><h2 id="五、flp-不可能性-fischer-lynch-paterson-1985" tabindex="-1">五、FLP 不可能性 (Fischer-Lynch-Paterson 1985) <a class="header-anchor" href="#五、flp-不可能性-fischer-lynch-paterson-1985" aria-label="Permalink to &quot;五、FLP 不可能性 (Fischer-Lynch-Paterson 1985)&quot;">​</a></h2><h3 id="定理" tabindex="-1">定理 <a class="header-anchor" href="#定理" aria-label="Permalink to &quot;定理&quot;">​</a></h3><p><strong>纯异步网络</strong> (消息延迟无上限) 下, <strong>如果有 1 个节点可能 crash</strong>, 那 deterministic consensus 算法无法保证 termination (eventually all correct 都 AGREE).</p><h3 id="证明-sketch" tabindex="-1">证明 sketch <a class="header-anchor" href="#证明-sketch" aria-label="Permalink to &quot;证明 sketch&quot;">​</a></h3><p>构造一个 initial configuration <code>C0</code> 是 bivalent—— 可 decide 0 or decide 1 (depend on 内部 schedule). 算法必须转 <code>C0</code> into a <code>0-valent</code> 或 <code>1-valent</code> state——但我们可以<strong>streer schedule</strong> 让一个<strong>关键步骤</strong> (e.g., 某个 message deliver) 在 system 处于 bivalent 时 crash 那么 node。去掉那个 message → system stays bivalent forever—— 阻止 termination.</p><h3 id="工程绕开" tabindex="-1">工程绕开 <a class="header-anchor" href="#工程绕开" aria-label="Permalink to &quot;工程绕开&quot;">​</a></h3><p>绕开 FLP:</p><ol><li><strong>Randomized consensus</strong>: 算法随机。 Paxos 用 randomized proposal number; Ben-Or 1983 也是 randomized. 阻止 indefinite 死锁.</li><li><strong>Failure detector with ◇S</strong>: eventual weak detector 允许 eventually &quot;skip crashed&quot;—— disconnect indefinite bivalent.</li><li><strong>Partial synchronous assumption</strong>: 实际 assumption &quot;eventual message delivery&quot;——一段 indefinite 第 phase 后总收得到 message。这与 eventual detector 一致.</li></ol><p>工程区间 distributed consensus algorithms 都 mix 这三种 trick.</p><hr><h2 id="六、不可靠故障检测的应用" tabindex="-1">六、不可靠故障检测的应用 <a class="header-anchor" href="#六、不可靠故障检测的应用" aria-label="Permalink to &quot;六、不可靠故障检测的应用&quot;">​</a></h2><h3 id="eureka-netflix-ap-failover" tabindex="-1">Eureka (Netflix) AP Failover <a class="header-anchor" href="#eureka-netflix-ap-failover" aria-label="Permalink to &quot;Eureka (Netflix) AP Failover&quot;">​</a></h3><p>Eureka server 之间的 replication 用 AP + eventual converge — 单 server crash (- circuit b/c lapsed -active); clients 调用 target 多 target 多 server 走 best-effort. Eureka heartbeat 每 30s lease 90s. <strong>可用性优先于一致</strong>, 默认 eventual heartbeat may show stale.</p><h3 id="cassandra-phi-accrual-adjustment" tabindex="-1">Cassandra Phi-Accrual Adjustment <a class="header-anchor" href="#cassandra-phi-accrual-adjustment" aria-label="Permalink to &quot;Cassandra Phi-Accrual Adjustment&quot;">​</a></h3><p>Cabbandra 默认 phi = 8. Failure with spiking traffic chatter: heartbeat delay 短 preservation phi=4 时小哥显 高但 adjust phi=12 reduce false-positive, 但 increase detection delays (慢) — SLA trade-off.</p><hr><h2 id="七、故障模型与算法选表" tabindex="-1">七、故障模型与算法选表 <a class="header-anchor" href="#七、故障模型与算法选表" aria-label="Permalink to &quot;七、故障模型与算法选表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Failure Model</th><th>Consensus 算法</th><th>Storage 算法</th><th>例</th></tr></thead><tbody><tr><td>Crash-stop</td><td>Paxos, Raft, Multi-Paxos</td><td>Primary-Backup, Chain Replication</td><td>Chubby, etcd</td></tr><tr><td>Crash-recovery</td><td>Paxos+log, ZAB</td><td>同上 + log replay</td><td>Zookeeper</td></tr><tr><td>Omission + crash</td><td>Paxos+◇S detector</td><td>同上 + retransmit</td><td>TCP, Cassandra</td></tr><tr><td>Byzantine</td><td>PBFT, HotStuff, Tendermint</td><td>Blockchains, some bank liveness</td><td>Bitcoin, Cosmos Hub</td></tr><tr><td>Hybrid</td><td>BFT hybrid Paxos 多副本 to Byzantine 内</td><td>集群 in/out cross-datacenter 太</td><td>跨云金融 system</td></tr></tbody></table><hr><h2 id="八、易错清单" tabindex="-1">八、易错清单 <a class="header-anchor" href="#八、易错清单" aria-label="Permalink to &quot;八、易错清单&quot;">​</a></h2><ol><li><strong>Pure async network + 1 crash impossible → 找绕</strong> : 算 deterministic consensus 必须 0 个 crash. 工程用 random + detector + bound message 释出 FLP.</li><li><strong>Lease 是 explicit 时间 grant, 不是 implicit structure</strong>: lease 没理清导致 leader skaring cluster extra; 心 延迟 timeout abide by overlap of 2+ lease. detected Oversize g超 leaked Trasure.</li><li><strong>Phi value vs fixed threshold</strong>: 不要 混用 &quot;5 秒 没心跳&quot; 与 phi, 前者 fail over war 不 平稳. 自动后 finalize entry process SQL form.</li><li><strong>Byzantine ≠ 不诚实硬件 BTC smart contract Byzantine</strong> : byzantine 假设攻击者不能 break cryptographic signature, 工程实际 alleviate 难度. BC store multi node crypto.</li><li><strong>FLP &quot;impossible&quot; ≠ 现实不能 consensus</strong>: FLP 论证 existence of indep scheduling let never choosing . 但实际 scheduled clock times 不知 form partial synchoronus path</li><li><strong>Crash recovery ≠ state must flush to disk</strong>: 没 fsync WAL 的 crash recovery 系统是 NOT crash-safe (new replica 读 data corruption state.consensus on false commit).</li><li><strong>leader lease + externalizing duree certain手机</strong>: 调度器 必 包含 grace time wait os difference treat。</li></ol><hr><h2 id="九、这一章带走的东西" tabindex="-1">九、这一章带走的东西 <a class="header-anchor" href="#九、这一章带走的东西" aria-label="Permalink to &quot;九、这一章带走的东西&quot;">​</a></h2><ol><li>Failure model 是 distributed algorithms 的底层假设——crash-stop 比 crash-recovery 简单, byzantine 最复杂。</li><li>Paxos/Raft 等 crash-stop consensus 上 exist in real-world via crash-recovery (用 fsync log).</li><li>Chandra-Toueg ◇S failure detector + asynchronous → Consensus 可解. Raft heartbeat + lease 是 implicit ◇S detector。</li><li>Phi-accrual failure detector 提供 continuous suspicion, configurable threshold, less false-positive。</li><li>FLP 不能解决 in purely asynchronous model. 工程 evasion: randomization + DETECTOR + partial synchronous assumption.</li><li>BFT 需要 3f+1 nodes 与 O(N²) communication, 工程上限定 budget ≤20 nodes 块 .</li></ol><hr><p>下一节 → <a href="./../consensus/">共识</a></p>`,90)])])}const g=a(o,[["render",n]]);export{p as __pageData,g as default};
